from scipy.optimize import least_squares
def model_h(p,form):
    a,b=p[0],p[1]
    if form=='sinlin':
        h=p[2]+p[3]*t+p[4]*np.sin(p[5]*t+p[6])
    elif form=='sinexp':
        h=p[2]+p[3]*np.sin(p[5]*t+p[6])*np.exp(-p[4]*t)
    elif form=='sin2':
        h=p[2]+p[3]*np.sin(p[5]*t+p[6])+p[4]*np.sin(2*p[5]*t+p[7])
    elif form=='sintlin':
        h=p[2]+p[3]*t+p[4]*np.sin(p[5]*t+p[6])+p[7]*t*np.sin(p[5]*t+p[6])*0
    return a*t+b*P*np.log(P)+h/P
def resid(p,form): return (model_h(p,form)-dP_dt)
